//! Does an `EnvFilter` directive match target strings by segment or by raw prefix?
//!
//! Decides SMA-557's central operator claim. We do NOT read tracing-subscriber's
//! source and reason about it — we run real filters against real targets.

use tracing::Level;
use tracing_subscriber::filter::EnvFilter;
use tracing_subscriber::layer::{Context, Filter};
use tracing_subscriber::prelude::*;
use tracing_subscriber::Registry;

/// Every target shape that exists in the Helikon workspace today, plus the
/// hypothetical prefix-collision case D1 would have to survive.
const TARGETS: &[&str] = &[
    "paigasus::openai::chat",
    "paigasus::litellm::stream",
    "paigasus::temporal::activities",
    "paigasus_helikon_core::session",
    "paigasus_helikon_runtime_axum::registry",
    "paigasus_helikon_providers_openai::backend::chat",
    // Hypothetical: a future component whose name extends an existing one.
    "paigasus::openai_compat::chat",
    // Control: must never match anything below.
    "hyper::client",
];

/// Ask a filter, for one directive and one target, whether a DEBUG event on
/// that target would be enabled. Uses the `Filter` trait's `enabled` with a
/// synthetic callsite-free metadata check via `callsite_enabled`-style probing
/// is awkward, so instead we drive real events through a counting layer.
fn probe(directive: &str) -> Vec<(&'static str, bool)> {
    TARGETS
        .iter()
        .map(|t| (*t, would_enable(directive, t)))
        .collect()
}

/// Build the filter and ask it about a synthetic DEBUG metadata for `target`.
fn would_enable(directive: &str, target: &'static str) -> bool {
    let filter = EnvFilter::new(directive);
    // A leaked 'static Metadata for the target under test.
    let meta: &'static tracing::Metadata<'static> = Box::leak(Box::new(tracing::Metadata::new(
        "probe",
        target,
        Level::DEBUG,
        None,
        None,
        None,
        tracing::field::FieldSet::new(&[], tracing::callsite::Identifier(&PROBE)),
        tracing::metadata::Kind::EVENT,
    )));
    let subscriber = Registry::default();
    tracing::subscriber::with_default(subscriber.into(), || {
        let cx: Context<'_, Registry> = Context::none();
        Filter::<Registry>::enabled(&filter, meta, &cx)
    })
}

struct Probe;
impl tracing::Callsite for Probe {
    fn set_interest(&self, _: tracing::subscriber::Interest) {}
    fn metadata(&self) -> &tracing::Metadata<'_> {
        unreachable!("probe callsite metadata is never requested")
    }
}
static PROBE: Probe = Probe;

fn main() {
    let directives = [
        "paigasus=debug",
        "paigasus::=debug",
        "paigasus::openai=debug",
        "off,paigasus::litellm::stream=trace",
        "paigasus_helikon_core=debug",
    ];

    for d in directives {
        println!("\n=== RUST_LOG='{d}' ===");
        for (target, enabled) in probe(d) {
            println!("  {:>5}  {target}", if enabled { "MATCH" } else { "-" });
        }
    }
}

//! Does an `EnvFilter` directive match target strings by segment or by raw prefix?
//!
//! Decides SMA-557's central operator claim. We do NOT read tracing-subscriber's
//! source and reason about it — we emit real `tracing` events with real literal
//! targets through a real subscriber and record which ones survive the filter.

use std::sync::{Arc, Mutex};

use tracing_subscriber::layer::{Context, Layer};
use tracing_subscriber::prelude::*;
use tracing_subscriber::{EnvFilter, Registry};

/// Records the target of every event that survives the filter.
#[derive(Clone, Default)]
struct Collector(Arc<Mutex<Vec<String>>>);

impl<S: tracing::Subscriber> Layer<S> for Collector {
    fn on_event(&self, event: &tracing::Event<'_>, _: Context<'_, S>) {
        self.0
            .lock()
            .expect("collector mutex")
            .push(event.metadata().target().to_owned());
    }
}

/// Emit one DEBUG event on each target shape present in the Helikon workspace
/// today, plus the prefix-collision case D1 would have to survive.
fn emit_all() {
    tracing::debug!(target: "paigasus::openai::chat", "x");
    tracing::debug!(target: "paigasus::litellm::stream", "x");
    tracing::debug!(target: "paigasus::temporal::activities", "x");
    tracing::debug!(target: "paigasus_helikon_core::session", "x");
    tracing::debug!(target: "paigasus_helikon_runtime_axum::registry", "x");
    // A future component whose name extends an existing one.
    tracing::debug!(target: "paigasus::openai_compat::chat", "x");
    // Control: must never match a paigasus directive.
    tracing::debug!(target: "hyper::client", "x");
}

const ALL: &[&str] = &[
    "paigasus::openai::chat",
    "paigasus::litellm::stream",
    "paigasus::temporal::activities",
    "paigasus_helikon_core::session",
    "paigasus_helikon_runtime_axum::registry",
    "paigasus::openai_compat::chat",
    "hyper::client",
];

fn run(directive: &str) -> Vec<String> {
    let collector = Collector::default();
    let subscriber = Registry::default().with(collector.clone().with_filter(EnvFilter::new(directive)));
    tracing::subscriber::with_default(subscriber, emit_all);
    let out = collector.0.lock().expect("collector mutex").clone();
    out
}

fn main() {
    for directive in [
        "paigasus=debug",
        "paigasus::=debug",
        "paigasus::openai=debug",
        "off,paigasus::litellm::stream=trace",
        "paigasus_helikon_core=debug",
    ] {
        let matched = run(directive);
        println!("\n=== RUST_LOG='{directive}' ===");
        for t in ALL {
            let hit = matched.iter().any(|m| m == t);
            println!("  {:>5}  {t}", if hit { "MATCH" } else { "-" });
        }
    }
}

